import{_ as r,o as a,c as e,a5 as o}from"./chunks/framework.B5tqjWbr.js";const g=JSON.parse('{"title":"PP-09 三电平 SVPWM - 知识检查","description":"","frontmatter":{"date":"2026-06-11T00:00:00.000Z","section":"电机控制","chapter":"power-path","chapterTitle":"功率链路","chapterOrder":40,"category":"功率链路","source":"motor","visibility":"public","title":"PP-09 三电平 SVPWM - 知识检查","tags":["motor-control"],"status":"learning","summary":"**模块编号：** PP-09 **题目数量：** 8 **验收目标：** 能从参考矢量定位到扇区和小三角形，计算基本作用时间，并说明冗余小矢量如何用于中点平衡。","navGroup":"基础与硬件","navGroupOrder":20},"headers":[],"relativePath":"content/motor/power-path/PP-09-assessment.md","filePath":"content/motor/power-path/PP-09-assessment.md","lastUpdated":1783096495000}'),s={name:"content/motor/power-path/PP-09-assessment.md"};function n(d,t,l,h,i,p){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="pp-09-三电平-svpwm-知识检查" tabindex="-1">PP-09 三电平 SVPWM - 知识检查 <a class="header-anchor" href="#pp-09-三电平-svpwm-知识检查" aria-label="Permalink to &quot;PP-09 三电平 SVPWM - 知识检查&quot;">​</a></h1><p><strong>模块编号：</strong> PP-09<br><strong>题目数量：</strong> 8<br><strong>验收目标：</strong> 能从参考矢量定位到扇区和小三角形，计算基本作用时间，并说明冗余小矢量如何用于中点平衡。</p><hr><h2 id="_1-矢量数量" tabindex="-1">1. 矢量数量 <a class="header-anchor" href="#_1-矢量数量" aria-label="Permalink to &quot;1. 矢量数量&quot;">​</a></h2><p><strong>问题：</strong> 三相三电平逆变器理论开关状态有多少种？空间矢量中为什么会出现冗余？</p><p><strong>答案：</strong> 每相 3 种状态，共 <code>3^3 = 27</code> 种开关状态。不同开关状态可能产生相同的线电压矢量，因此存在冗余矢量，特别是小矢量。</p><hr><h2 id="_2-与二电平-svpwm-的差异" tabindex="-1">2. 与二电平 SVPWM 的差异 <a class="header-anchor" href="#_2-与二电平-svpwm-的差异" aria-label="Permalink to &quot;2. 与二电平 SVPWM 的差异&quot;">​</a></h2><p><strong>问题：</strong> 三电平 SVPWM 相比二电平 SVPWM 多出的核心控制目标是什么？</p><p>A. 只提高基波幅值<br> B. 只降低 PWM 频率<br> C. 同时处理冗余矢量选择和中点电位平衡<br> D. 取消死区时间</p><p><strong>答案：</strong> C</p><hr><h2 id="_3-扇区与小三角形" tabindex="-1">3. 扇区与小三角形 <a class="header-anchor" href="#_3-扇区与小三角形" aria-label="Permalink to &quot;3. 扇区与小三角形&quot;">​</a></h2><p><strong>任务：</strong> 对一个位于第一大扇区的参考矢量，说明三电平 SVPWM 需要继续判断小三角形的原因。</p><p><strong>参考答案：</strong> 第一大扇区内部由多个小三角形组成，不同小三角形对应不同相邻矢量组合。只判断大扇区无法唯一确定作用矢量和作用时间。</p><hr><h2 id="_4-作用时间合法性" tabindex="-1">4. 作用时间合法性 <a class="header-anchor" href="#_4-作用时间合法性" aria-label="Permalink to &quot;4. 作用时间合法性&quot;">​</a></h2><p><strong>问题：</strong> 任意采样周期内，三个相邻矢量作用时间应满足什么约束？</p><p><strong>答案：</strong> <code>T1 &gt;= 0</code>、<code>T2 &gt;= 0</code>、<code>T0 &gt;= 0</code>，且 <code>T1 + T2 + T0 = Ts</code>。若任一时间为负，说明扇区判断或过调制处理错误。</p><hr><h2 id="_5-中点平衡策略" tabindex="-1">5. 中点平衡策略 <a class="header-anchor" href="#_5-中点平衡策略" aria-label="Permalink to &quot;5. 中点平衡策略&quot;">​</a></h2><p><strong>问题：</strong> 冗余小矢量如何影响中点电压？</p><p><strong>参考答案：</strong> 同一输出矢量可由不同开关状态实现，这些状态对中点电流方向不同。根据 <code>Vupper - Vlower</code> 和相电流方向选择冗余状态，可以让中点电流朝降低偏差的方向流动。</p><hr><h2 id="_6-仿真验收" tabindex="-1">6. 仿真验收 <a class="header-anchor" href="#_6-仿真验收" aria-label="Permalink to &quot;6. 仿真验收&quot;">​</a></h2><p><strong>任务：</strong> 建立三电平 SVPWM 仿真，并与二电平 SVPWM 对比。</p><p><strong>验收标准：</strong></p><div class="kb-table-scroll"><table><thead><tr><th>指标</th><th>阈值</th></tr></thead><tbody><tr><td>duty 合法性</td><td>100% 在 <code>[0, 1]</code></td></tr><tr><td>线电压电平</td><td>三电平输出层级正确</td></tr><tr><td>基波幅值误差</td><td>与理论值误差 &lt; 3%</td></tr><tr><td>中点电压偏移</td><td>平衡策略开启后 RMS 偏移下降</td></tr></tbody></table></div><hr><h2 id="_7-过调制边界" tabindex="-1">7. 过调制边界 <a class="header-anchor" href="#_7-过调制边界" aria-label="Permalink to &quot;7. 过调制边界&quot;">​</a></h2><p><strong>问题：</strong> 三电平 SVPWM 进入过调制区时，最先应保证哪条底线？</p><p><strong>答案：</strong> duty 和开关状态必须合法，矢量作用时间不能产生负时间；中点平衡可降级，但不能造成直通、占空比越界或不可实现状态。</p><hr><h2 id="_8-lxfoc-接口思考" tabindex="-1">8. lxfoc 接口思考 <a class="header-anchor" href="#_8-lxfoc-接口思考" aria-label="Permalink to &quot;8. lxfoc 接口思考&quot;">​</a></h2><p><strong>问题：</strong> 70% 阶段为什么不要求 lxfoc 直接实现三电平硬件输出？</p><p><strong>参考答案：</strong> lxfoc 当前定位是硬件无关算法库。三电平输出需要强绑定驱动、采样、中点电压和保护硬件。70% 阶段先完成知识库推导与仿真闭环，并定义未来接口，避免在没有硬件验证时伪装成可部署功能。</p><hr><h2 id="评分" tabindex="-1">评分 <a class="header-anchor" href="#评分" aria-label="Permalink to &quot;评分&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th style="text-align:right;">得分</th><th>评价</th></tr></thead><tbody><tr><td style="text-align:right;">7-8</td><td>可进入三电平工程化专题</td></tr><tr><td style="text-align:right;">5-6</td><td>需要补充小三角形与中点平衡</td></tr><tr><td style="text-align:right;">&lt;5</td><td>需要回到 PP-08 与二电平 SVPWM 基础</td></tr></tbody></table></div>',39)])])}const P=r(s,[["render",n]]);export{g as __pageData,P as default};
